item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic in,
    output logic out
);
    assign out = in;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic in;
    wire out;
    integer checks = 0;
    TopModule dut (.in(in), .out(out));

    task automatic check_value(input logic value);
        in = value;
        #1;
        if (out !== value)
            $fatal(1, "FAIL: in=%b out=%b", value, out);
        checks = checks + 1;
    endtask

    initial begin
        check_value(1'"'b0);
        check_value(1'b1);
        check_value(1'b0);
        check_value(1'b1);
        check_value(1'bx);
        check_value(1'bz);
        check_value(1'b0);
        "'$display("PASS: %0d identity checks", checks);
        $finish;
    end

    initial begin
        #100;
        $fatal(1, "FAIL: development simulation timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim.vvp candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
echo "$compile_status" > dev_compile.exit
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim.vvp > dev_simulation.log 2>&1
    echo "$?" > dev_simulation.exit
fi'

